"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4926],{74926:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard\\n          cover=\\"/assets/snippets/books/the-origin-of-species.png\\"\\n          title=\\"종의 기원\\"\\n          author=\\"정유정\\"\\n          publisher=\\"은행나무\\"\\n          publishedDate=\\"2016-05-16\\"\\n          isbn=\\"9788956609959\\"\\n          rating=5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n자신의 집에서 피 냄새를 맡으며 잠에서 깨어나는 장면으로 작품은 시작된다.  \\n전날 밤부터의 기억이 끊겨 있고, 자신의 온몸은 피투성이다.  \\n아래층으로 내려간 그는 면도칼에 목이 그여 살해된 어머니의 시신을 발견한다.  \\n끔찍한 상황 속에서 머릿속을 지배하는 생각은 단 하나, ```어젯밤, 이 집에서 무슨 일이 있었던 걸까?```  \\n<br>\\n이러한 상황 속에서 독자는 주인공과 함께 혼란과 공포 속에 범인을 추리해 나가게 된다.  \\n<br>\\n이 작품은 <mark>순수한 악</mark> 그 자체를 탐구한다.  \\n정유정 작가님이 꾸준히 파고들어 온 ```악```이라는 주제를 가장 깊고 본질적인 차원에서 접근한 책이 아닌가 생각이 든다.  \\n<br>\\n개인적으로 1인칭 시점으로 독자와 함께 진실을 알아가는 과정과 충격적인 진실이 인상에 남는다.  "}')}}]);